import { createHash, timingSafeEqual } from 'crypto';
import { EventEmitter } from 'events';

interface TenantConfig {
  tenantId: string;
  logLevel: 'debug' | 'info' | 'warn' | 'error';
  retentionDays: number;
  allowedTags: string[];
}

interface LogEntry {
  timestamp: number;
  tenantId: string;
  level: string;
  message: string;
  tags: string[];
  metadata?: Record<string, unknown>;
}

class TenantConfigCache {
  private cache: Map<string, { config: TenantConfig; expires: number }> = new Map();
  private readonly ttlMs: number;

  constructor(ttlMs: number = 300000) {
    this.ttlMs = ttlMs;
  }

  computeCacheKey(tenantId: string, context?: string): string {
    const normalizedId = tenantId.trim().toLowerCase();
    const base = context ? `${normalizedId}\x00${context}` : normalizedId;
    return createHash('sha256').update(base).digest('hex').substring(0, 16);
  }

  get(tenantId: string, context?: string): TenantConfig | null {
    const key = this.computeCacheKey(tenantId, context);
    const entry = this.cache.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expires) {
      this.cache.delete(key);
      return null;
    }
    return entry.config;
  }

  set(tenantId: string, config: TenantConfig, context?: string): void {
    const key = this.computeCacheKey(tenantId, context);
    this.cache.set(key, {
      config,
      expires: Date.now() + this.ttlMs
    });
  }

  invalidate(tenantId: string, context?: string): void {
    const key = this.computeCacheKey(tenantId, context);
    this.cache.delete(key);
  }
}

class LogRouter {
  private configCache: TenantConfigCache;
  private logBuffer: Map<string, LogEntry[]> = new Map();
  private emitter: EventEmitter;

  constructor(cacheTtl?: number) {
    this.configCache = new TenantConfigCache(cacheTtl);
    this.emitter = new EventEmitter();
  }

  async registerTenant(config: TenantConfig): Promise<void> {
    if (!config.tenantId || config.tenantId.length > 128) {
      throw new Error('Invalid tenant ID');
    }
    this.configCache.set(config.tenantId, config);
    this.logBuffer.set(config.tenantId, []);
  }

  private resolveEffectiveConfig(tenantId: string, requestContext?: string): TenantConfig | null {
    // First check context-specific config
    if (requestContext) {
      const contextConfig = this.configCache.get(tenantId, requestContext);
      if (contextConfig) return contextConfig;
    }
    // Fall back to base tenant config
    return this.configCache.get(tenantId);
  }

  async ingestLog(entry: LogEntry, requestContext?: string): Promise<boolean> {
    const config = this.resolveEffectiveConfig(entry.tenantId, requestContext);
    if (!config) {
      this.emitter.emit('rejected', { reason: 'no_config', tenantId: entry.tenantId });
      return false;
    }

    // Verify tenant isolation
    if (config.tenantId !== entry.tenantId) {
      this.emitter.emit('rejected', { reason: 'tenant_mismatch', tenantId: entry.tenantId });
      return false;
    }

    // Validate tags against allowed list
    const invalidTags = entry.tags.filter(t => !config.allowedTags.includes(t));
    if (invalidTags.length > 0) {
      this.emitter.emit('warning', { reason: 'invalid_tags', tags: invalidTags });
      entry.tags = entry.tags.filter(t => config.allowedTags.includes(t));
    }

    // Buffer the log
    const buffer = this.logBuffer.get(entry.tenantId);
    if (buffer) {
      buffer.push(entry);
    }
    return true;
  }

  async setContextOverride(tenantId: string, context: string, overrideConfig: Partial<TenantConfig>): Promise<void> {
    const baseConfig = this.configCache.get(tenantId);
    if (!baseConfig) {
      throw new Error('Tenant not registered');
    }
    const merged: TenantConfig = { ...baseConfig, ...overrideConfig, tenantId: baseConfig.tenantId };
    this.configCache.set(tenantId, merged, context);
  }

  getBufferedLogs(tenantId: string): LogEntry[] {
    return this.logBuffer.get(tenantId) || [];
  }

  onEvent(event: string, handler: (...args: any[]) => void): void {
    this.emitter.on(event, handler);
  }
}

// Multi-tenant monitoring agent
class MonitoringAgent {
  private router: LogRouter;
  // Store SHA-256 hashes of secrets rather than plaintext (CWE-256)
  private tenantSecrets: Map<string, Buffer> = new Map();

  constructor() {
    this.router = new LogRouter(60000);
  }

  private hashSecret(secret: string): Buffer {
    return createHash('sha256').update(secret, 'utf8').digest();
  }

  async onboardTenant(tenantId: string, secret: string, config: Omit<TenantConfig, 'tenantId'>): Promise<void> {
    const fullConfig: TenantConfig = { ...config, tenantId };
    await this.router.registerTenant(fullConfig);
    this.tenantSecrets.set(tenantId, this.hashSecret(secret));
  }

  authenticateTenant(tenantId: string, providedSecret: string): boolean {
    const stored = this.tenantSecrets.get(tenantId);
    if (!stored) return false;
    const provided = this.hashSecret(providedSecret);
    // Constant-time comparison to prevent timing attacks (CWE-208)
    if (provided.length !== stored.length) return false;
    return timingSafeEqual(provided, stored);
  }

  async submitLog(tenantId: string, secret: string, entry: Omit<LogEntry, 'tenantId' | 'timestamp'>, context?: string): Promise<boolean> {
    if (!this.authenticateTenant(tenantId, secret)) {
      return false;
    }
    const fullEntry: LogEntry = {
      ...entry,
      tenantId,
      timestamp: Date.now()
    };
    return this.router.ingestLog(fullEntry, context);
  }

  async setOverride(tenantId: string, secret: string, context: string, override: Partial<TenantConfig>): Promise<boolean> {
    if (!this.authenticateTenant(tenantId, secret)) {
      return false;
    }
    await this.router.setContextOverride(tenantId, context, override);
    return true;
  }

  getLogs(tenantId: string, secret: string): LogEntry[] | null {
    if (!this.authenticateTenant(tenantId, secret)) {
      return null;
    }
    return this.router.getBufferedLogs(tenantId);
  }
}

export { MonitoringAgent, LogRouter, TenantConfigCache, TenantConfig, LogEntry };
